 * Header portion (in a multi-file app, move this to isr_ring.h)
 * ========================================================================== */

struct isr_ring {
    atomic_t head;         /* next slot the producer will write (monotonic, wraps mod 2^N) */
    atomic_t tail;         /* next slot the consumer will read (monotonic, wraps mod 2^N) */
    const size_t size;     /* capacity in bytes, >= 1 */
    uint8_t *data;         /* caller-owned storage */
};

/* Initialize the ring buffer. Not thread-safe; call before use. */
static inline void isr_ring_init(struct isr_ring *rb, uint8_t *storage, size_t size)
{
    K_ASSERT(size > 0);
    rb->data = storage;
    rb->size = size;
    atomic_set(&rb->head, 0);
    atomic_set(&rb->tail, 0);
}

/*
 * Producer side -- safe to call from ISR context.
 * Non-blocking: stores up to `len` bytes, returns the number stored
 * (0 if the buffer is full, or fewer if only part fits -- overflow is
 * dropped). FIFO order is always preserved.
 */
static inline size_t isr_ring_write(struct isr_ring *rb, const uint8_t *data, size_t len);

static inline size_t isr_ring_write_byte(struct isr_ring *rb, uint8_t b)
{
    return isr_ring_write(rb, &b, 1);
}

/*
 * Consumer side -- intended for thread context.
 * Non-blocking: reads up to `len` bytes, returns the number read
 * (0 if empty). FIFO order is always preserved.
 */
static inline size_t isr_ring_read(struct isr_ring *rb, uint8_t *data, size_t len);

static inline size_t isr_ring_read_byte(struct isr_ring *rb, uint8_t *b)
{
    return isr_ring_read(rb, b, 1);
}

/* Usable from either context. */
static inline size_t isr_ring_bytes_avail(const struct isr_ring *rb);
static inline size_t isr_ring_space_avail(const struct isr_ring *rb);
static inline bool isr_ring_is_empty(const struct isr_ring *rb)
{
    return isr_ring_bytes_avail(rb) == 0;
}
static inline bool isr_ring_is_full(const struct isr_ring *rb)
{
    return isr_ring_space_avail(rb) == 0;
}

/* ==========================================================================
 * Implementation
 * ========================================================================== */

/* Number of bytes currently in the buffer.
 * Invariant: 0 <= tail <= head <= tail + size, so the unsigned difference
 * is always correct, even across 2^N wrap of the counters. */
static inline size_t isr_ring_filled(const struct isr_ring *rb)
{
    return (size_t)atomic_get(&rb->head) - (size_t)atomic_get(&rb->tail);
}

static inline size_t isr_ring_bytes_avail(const struct isr_ring *rb)
{
    return isr_ring_filled(rb);
}

static inline size_t isr_ring_space_avail(const struct isr_ring *rb)
{
    return rb->size - isr_ring_filled(rb);
}

static inline size_t isr_ring_write(struct isr_ring *rb, const uint8_t *data, size_t len)
{
    size_t head = (size_t)atomic_get(&rb->head);
    size_t tail = (size_t)atomic_get(&rb->tail);
    size_t space = rb->size - (head - tail);
    size_t off = head % rb->size;
    size_t first;

    if (len > space) {
        len = space;               /* non-blocking: drop overflow */
    }
    if (len == 0) {
        return 0;
    }

    /* Copy in at most 2 contiguous chunks, split at the wrap point.
     * Since filled < size, `off` never equals the slot the consumer
     * currently holds (tail % size), so we never stomp on data that
     * hasn't been consumed. */
    first = rb->size - off;
    if (first > len) {
        first = len;
    }
    memcpy(rb->data + off, data, first);
    if (len > first) {
        memcpy(rb->data, data + first, len - first);
    }

    /* Publish: the fence ensures the data stores complete before the
     * head store becomes visible to the consumer. */
    arch_mem_fence();
    atomic_set(&rb->head, (atomic_val_t)(head + len));
    return len;
}

static inline size_t isr_ring_read(struct isr_ring *rb, uint8_t *data, size_t len)
{
    size_t head = (size_t)atomic_get(&rb->head);
    size_t tail = (size_t)atomic_get(&rb->tail);
    size_t avail = head - tail;
    size_t off = tail % rb->size;
    size_t first;

    if (len > avail) {
        len = avail;               /* non-blocking: read what's there */
    }
    if (len == 0) {
        return 0;
    }

    first = rb->size - off;
    if (first > len) {
        first = len;
    }
    memcpy(data, rb->data + off, first);
    if (len > first) {
        memcpy(data + first, rb->data, len - first);
    }

    /* Fence before publishing tail: ensures our data loads have
     * completed before the producer is allowed to reuse those slots. */
    arch_mem_fence();
    atomic_set(&rb->tail, (atomic_val_t)(tail + len));
    return len;
}
```

