```c
/*
 * isr_ring.c -- Lock-free SPSC ring buffer for Zephyr RTOS
 *
 * Usage in a Zephyr app:
 *   - Drop this file in the app (or split into isr_ring.h/.c along the
 *     section boundaries marked below).
 *   - No Kconfig changes are required; the self-test main() at the end
 *     can be removed if only the buffer itself is needed.
 *
 * Contexts:
 *   isr_ring_write*()  -> ISR context (producer)
 *   isr_ring_read*()   -> thread context (consumer)
 *
 * Guarantees:
 *   - Lock-free: single-word atomic loads/stores + memory fences only.
 *     No mutexes, no spinlocks, no allocation, no blocking -- the ISR
 *     never waits.
 *   - FIFO order is always preserved.
 *   - Full: excess bytes are dropped (write returns the number stored).
 *   - Empty: read returns 0.
 *   - 100% of the capacity is usable (monotonic indices make
 *     head==tail unambiguous).
 */

#include <zephyr/kernel.h>
#include <zephyr/sys/atomic.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

/* =====================================================================
 * Header portion  (in a 2-file layout, this is isr_ring.h)
 * ===================================================================== */

struct isr_ring {
	/* Next slot the producer will write. Monotonically increasing
	 * (wraps mod 2^32); the fill count is head - tail, so "full"
	 * and "empty" are never ambiguous. */
	atomic_t head;
	/* Next slot the consumer will read. Same convention as head. */
	atomic_t tail;
	const size_t size;	/* Capacity in bytes (>= 1) */
	uint8_t *data;		/* Caller-owned storage, any alignment */
};

/*
 * Initialize the ring buffer. Must be called before use (and when
 * re-initializing, no other context may be touching the buffer).
 */
static inline void isr_ring_init(struct isr_ring *rb, uint8_t *storage, size_t size)
{
	if (size == 0) {
		return;
	}
	rb->data = storage;
	rb->size = size;
	atomic_set(&rb->head, 0);
	atomic_set(&rb->tail, 0);
}

/*
 * Producer -- call from ISR context.
 * Non-blocking. Stores up to `len` bytes; returns the number actually
 * stored (0 if the buffer is full, less than len if it only partially
 * fit -- overflow is dropped from the end of the chunk). FIFO order is
 * preserved.
 */
static inline size_t isr_ring_write(struct isr_ring *rb, const uint8_t *data, size_t len);

static inline size_t isr_ring_write_byte(struct isr_ring *rb, uint8_t b)
{
	return isr_ring_write(rb, &b, 1);
}

/*
 * Consumer -- call from thread context.
 * Non-blocking. Reads up to `len` bytes; returns the number actually
 * read (0 if the buffer is empty). FIFO order is preserved.
 *
 * Blocking-style consumption in thread context:
 *   while (isr_ring_read_byte(&rb, &b) == 0) {
 *       k_busy_wait(10);          /* or k_sem / k_msgq for wakeup-based */
 *   }
 */
static inline size_t isr_ring_read(struct isr_ring *rb, uint8_t *data, size_t len);

static inline size_t isr_ring_read_byte(struct isr_ring *rb, uint8_t *b)
{
	return isr_ring_read(rb, b, 1);
}

/* Usable from either context (single-word atomic loads only). */
static inline size_t isr_ring_bytes_avail(const struct isr_ring *rb);
static inline size_t isr_ring_space_avail(const struct isr_ring *rb);
static inline bool isr_ring_is_empty(const struct isr_ring *rb)
{
	return isr_ring_bytes_avail(rb) == 0;
}
static inline bool isr_ring_is_full(const struct isr_ring *rb)
{
	return isr_ring_space_avail(rb) == 0;
}

/* =====================================================================
 * Implementation
 * ===================================================================== */

/*
 * Number of bytes currently in the buffer.
 * Invariant: 0 <= tail <= head <= tail + size, maintained because the
 * producer only advances head up to tail + size and the consumer only
 * advances tail up to head. Unsigned subtraction makes the difference
 * correct even across 2^N wrap of the counters.
 */
static inline size_t isr_ring_filled(const struct isr_ring *rb)
{
	return (size_t)atomic_get(&rb->head) - (size_t)atomic_get(&rb->tail);
}

static inline size_t isr_ring_bytes_avail(const struct isr_ring *rb)
{
	return isr_ring_filled(rb);
}

static inline size_t isr_ring_space_avail(const struct isr_ring *rb)
{
	return rb->size - isr_ring_filled(rb);
}

static inline size_t isr_ring_write(struct isr_ring *rb, const uint8_t *data, size_t len)
{
	size_t head = (size_t)atomic_get(&rb->head);
	size_t tail = (size_t)atomic_get(&rb->tail);
	size_t space = rb->size - (head - tail);
	size_t off = head % rb->size;
	size_t first;

	if (len > space) {
		len = space;		/* full: drop the overflow */
	}
	if (len == 0) {
		return 0;
	}

	/*
	 * Copy in at most 2 contiguous chunks, split at the wrap point.
	 * Since filled < size at this point, `off` can never equal the
	 * slot the consumer currently holds (tail % size), so we never
	 * overwrite unconsumed data.
	 */
	first = rb->size - off;
	if (first > len) {
		first = len;
	}
	memcpy(rb->data + off, data, first);
	if (len > first) {
		memcpy(rb->data, data + first, len - first);
	}

	/*
	 * Publish the new head. The fence orders the data stores before
	 * the head store, so the consumer can never observe a new head
	 * (and start reading) before the data is in place.
	 */
	arch_mem_fence();
	atomic_set(&rb->head, (atomic_val_t)(head + len));
	return len;
}

static inline size_t isr_ring_read(struct isr_ring *rb, uint8_t *data, size_t len)
{
	size_t head = (size_t)atomic_get(&rb->head);
	size_t tail = (size_t)atomic_get(&rb->tail);
	size_t avail = head - tail;
	size_t off = tail % rb->size;
	size_t first;

	if (len > avail) {
		len = avail;		/* empty/partial: read what's there */
	}
	if (len == 0) {
		return 0;
	}

	first = rb->size - off;
	if (first > len) {
		first = len;
	}
	memcpy(data, rb->data + off, first);
	if (len > first) {
		memcpy(data + first, rb->data, len - first);
	}

	/*
	 * Publish the new tail. The fence orders our data loads before
	 * the tail store, so the producer is never allowed to reuse
	 * (overwrite) a slot we haven't finished reading.
	 */
	arch_mem_fence();
	atomic_set(&rb->tail, (atomic_val_t)(tail + len));
	return len;
}
