```c
/*
 * isr_ring.c -- Lock-free SPSC (single-producer/single-consumer) ring
 *              buffer for Zephyr RTOS, designed for an ISR producer
 *              and a thread consumer.
 *
 * Contexts
 *   isr_ring_write*()   ISR context (producer)
 *   isr_ring_read*()    thread context (consumer)
 *   isr_ring_bytes/space_avail(), isr_ring_is_empty/full()
 *                       either context
 *
 * Properties
 *   - Lock-free: only single-word atomic loads/stores and memory
 *     fences. No mutexes, no spinlocks, no allocation, no blocking
 *     calls, and nothing that would be illegal in ISR context.
 *     The producer never waits: if the buffer is full, the excess
 *     bytes are dropped and the number actually stored is returned.
 *   - FIFO order is always preserved.
 *   - 100% of the capacity is usable: head and tail are monotonically
 *     increasing counters (wrapping mod 2^N), so the fill count
 *     `head - tail` is unambiguous -- there's no "is head==tail
 *     empty or full" problem, and no slot is wasted.
 *   - SPSC only. If you need multi-producer or multi-consumer access,
 *     add a lock or use a CAS-based design instead.
 *
 * Typical usage
 *   static uint8_t uart_rx_mem[1024];
 *   static struct isr_ring uart_rx;
 *
 *   void early_init(void)
 *   {
 *       isr_ring_init(&uart_rx, uart_rx_mem, sizeof(uart_rx_mem));
 *   }
 *
 *   ISR context (e.g. UART RX interrupt):
 *       isr_ring_write_byte(&uart_rx, data_from_hw);
 *
 *   Thread context:
 *       uint8_t buf[64];
 *       while (isr_ring_read(&uart_rx, buf, sizeof(buf)) > 0) {
 *           /* handle buf */
 *       }
 *
 * Build note: no Kconfig options are needed. The self-test at the
 * end of this file (and main()) can be excluded by defining
 * ISR_RING_NO_SELF_TEST when using the buffer as a library only.
 */

#include <zephyr/kernel.h>
#include <zephyr/sys/atomic.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

/* ==========================================================================
 * Header portion
 * (in a 2-file layout, everything in this section becomes isr_ring.h)
 * ========================================================================== */

struct isr_ring {
	/*
	 * Next slot the producer will write. Monotonically increasing,
	 * wrapping mod 2^N. The fill count is (head - tail) taken as
	 * unsigned, which stays correct across the wrap as long as
	 * head - tail < 2^N - size (in practice, always).
	 */
	atomic_t head;
	/* Next slot the consumer will read, same convention. */
	atomic_t tail;
	const size_t size;	/* Capacity in bytes (>= 1) */
	uint8_t *data;		/* Caller-owned storage (don't free/modify during use) */
};

/*
 * Initialize the ring buffer. Call before use; while re-initializing,
 * no other context may be accessing the buffer.
 */
static inline void isr_ring_init(struct isr_ring *rb, uint8_t *storage, size_t size)
{
	if (size == 0) {
		return;
	}

	rb->data = storage;
	rb->size = size;
	atomic_set(&rb->head, 0);
	atomic_set(&rb->tail, 0);
}

/*
 * Producer -- call from ISR context.
 *
 * Non-blocking. Stores up to `len` bytes in FIFO order and returns
 * the number of bytes actually stored:
 *   - 0            buffer is full
 *   - 0 < n < len  partial fit; the tail of the chunk is dropped
 *   - len          all of it fit
 */
static inline size_t isr_ring_write(struct isr_ring *rb, const uint8_t *data,
				     size_t len);

static inline size_t isr_ring_write_byte(struct isr_ring *rb, uint8_t b)
{
	return isr_ring_write(rb, &b, 1);
}

/*
 * Consumer -- call from thread context.
 *
 * Non-blocking. Reads up to `len` bytes in FIFO order and returns the
 * number of bytes actually read (0 if empty).
 *
 * For blocking-style consumption, wrap in a wait loop in thread
 * context:
 *   while (isr_ring_read_byte(&rb, &b) == 0) {
 *       k_busy_wait(10);   /* or use k_sem / k_msgq for wakeup */
 *   }
 */
static inline size_t isr_ring_read(struct isr_ring *rb, uint8_t *data, size_t len);

static inline size_t isr_ring_read_byte(struct isr_ring *rb, uint8_t *b)
{
	return isr_ring_read(rb, b, 1);
}

/* Safe to call from either context (single-word atomic loads only). */
static inline size_t isr_ring_bytes_avail(const struct isr_ring *rb);
static inline size_t isr_ring_space_avail(const struct isr_ring *rb);

static inline bool isr_ring_is_empty(const struct isr_ring *rb)
{
	return isr_ring_bytes_avail(rb) == 0;
}

static inline bool isr_ring_is_full(const struct isr_ring *rb)
{
	return isr_ring_space_avail(rb) == 0;
}

/* ==========================================================================
 * Implementation
 * ========================================================================== */

/*
 * Number of bytes currently in the buffer.
 *
 * Invariant maintained by the API below: 0 <= tail <= head and
 * head - tail <= size. The producer never advances head beyond
 * tail + size, and the consumer never advances tail beyond head, so
 * the unsigned difference is the fill count, even across counter
 * wrap.
 */
static inline size_t isr_ring_filled(const struct isr_ring *rb)
{
	return (size_t)atomic_get(&rb->head) - (size_t)atomic_get(&rb->tail);
}

static inline size_t isr_ring_bytes_avail(const struct isr_ring *rb)
{
	return isr_ring_filled(rb);
}

static inline size_t isr_ring_space_avail(const struct isr_ring *rb)
{
	return rb->size - isr_ring_filled(rb);
}

static inline size_t isr_ring_write(struct isr_ring *rb, const uint8_t *data,
				     size_t len)
{
	size_t head = (size_t)atomic_get(&rb->head);
	size_t tail = (size_t)atomic_get(&rb->tail);
	size_t space = rb->size - (head - tail);
	size_t off = head % rb->size;
	size_t first;

	if (len > space) {
		len = space;		/* full: drop the overflow */
	}
	if (len == 0) {
		return 0;
	}

	/*
	 * Copy in at most 2 contiguous chunks, split at the wrap point.
	 * Since the buffer isn't full at this point, `off` can't equal
	 * the slot the consumer currently holds (tail % size), so we
	 * never overwrite unconsumed data.
	 */
	first = rb->size - off;
	if (first > len) {
		first = len;
	}
	memcpy(rb->data + off, data, first);
	if (len > first) {
		memcpy(rb->data, data + first, len - first);
	}

	/*
	 * Publish the new head. The fence orders the data stores above
	 * the head store, so the consumer can never observe the new
	 * head (and start reading the data) before the data is in
	 * place.
	 */
	arch_mem_fence();
	atomic_set(&rb->head, (atomic_val_t)(head + len));

	return len;
}

static inline size_t isr_ring_read(struct isr_ring *rb, uint8_t *data, size_t len)
{
	size_t head = (size_t)atomic_get(&rb->head);
	size_t tail = (size_t)atomic_get(&rb->tail);
	size_t avail = head - tail;
	size_t off = tail % rb->size;
	size_t first;

	if (len > avail) {
		len = avail;		/* empty/partial: read what's there */
	}
	if (len == 0) {
		return 0;
	}

	/*
	 * Fence after loading head, so the data loads below are
	 * ordered after the head load -- we can never read a slot
	 * whose contents we haven't actually been told exist yet.
	 */
	arch_mem_fence();

	first = rb->size - off;
	if (first > len) {
		first = len;
	}
	memcpy(data, rb->data + off, first);
	if (len > first) {
		memcpy(data + first, rb->data, len - first);
	}

	/*
	 * Publish the new tail. The fence orders our data loads above
	 * the tail store, so the producer is never allowed to reuse
	 * (overwrite) a slot we haven't finished reading.
	 */
	arch_mem_fence();
	atomic_set(&rb->tail, (atomic_val_t)(tail + len));

	return len;
}
