	TEST_CHECK(!isr_ring_is_full(&rb));
	TEST_CHECK(isr_ring_read_byte(&rb, &b) == 0);
	TEST_CHECK(isr_ring_bytes_avail(&rb) == 0);
	TEST_CHECK(isr_ring_space_avail(&rb) == sizeof(storage));
}

static void test_fifo_and_wrap(void)
{
	static uint8_t storage[100];
	uint8_t wr[53];
	uint8_t rd[37];
	struct isr_ring rb;
	size_t total = 1000;
	size_t wi = 0;		/* logical write position */
	size_t ri = 0;		/* logical read (expected) position */

	isr_ring_init(&rb, storage, sizeof(storage));

	/*
	 * Write chunks of up to 53 bytes, read chunks of up to 37
	 * bytes. Chunk sizes and storage size are pairwise coprime,
	 * so the head/tail indices repeatedly wrap around the storage
	 * during the test. Byte values encode the position mod 251
	 * (coprime with 100), so a mis-order or wrap bug shows up as
	 * a sequence mismatch.
	 */
	while (ri < total) {
		while (isr_ring_bytes_avail(&rb) > 0 && ri < total) {
			size_t n = isr_ring_read(&rb, rd,
						  RING_MIN(37, isr_ring_bytes_avail(&rb)));

			for (size_t i = 0; i < n; i++) {
				if (rd[i] != (uint8_t)(ri % 251)) {
					test_failures++;
					printk("seq err at %zu: got %u want %u\n",
					       (unsigned int)ri, (unsigned int)rd[i],
					       (unsigned int)(ri % 251));
				}
				ri++;
			}
		}
		if (wi < total) {
			size_t n = RING_MIN(53, total - wi);

			for (size_t i = 0; i < n; i++) {
				wr[i] = (uint8_t)(wi % 251);
			}
			/* After the drain above, the buffer is empty, so the whole
			 * chunk must fit. */
			TEST_CHECK(isr_ring_write(&rb, wr, n) == n);
			wi += n;
		}
	}

	TEST_CHECK(isr_ring_is_empty(&rb));
}
