ISR test:

```c
static struct isr_ring isr_ring;
static uint8_t isr_ring_storage[256];
static volatile uint32_t isr_bytes_accepted;
static volatile uint8_t isr_seq;
static atomic_t isr_phase_done;

/*
 * Runs in real ISR context on every sysclock tick: the "producer"
 * writes the next byte of the sequence. If the ring is full, the byte
 * is dropped and the sequence number is *not* advanced, so the
 * accepted stream is always exactly 0, 1, 2, ..., and the consumer
 * can verify that.
 */
static void isr_producer(void)
{
	if (isr_ring_write_byte(&isr_ring, isr_seq) != 0) {
		isr_seq++;
		isr_bytes_accepted++;
	}
}

static K_THREAD_STACK_DEFINE(consumer_stack, 1024);
static struct k_thread consumer_thread;
static uint32_t consumer_bytes;
static int consumer_errors;

static void consumer_main(void *arg1, void *arg2, void *arg3)
{
	uint8_t rd[64];

	ARG_UNUSED(arg1);
	ARG_UNUSED(arg2);
	ARG_UNUSED(arg3);

	while (true) {
		size_t n = isr_ring_read(&isr_ring, rd, sizeof(rd));

		for (size_t i = 0; i < n; i++) {
			if (rd[i] != (uint8_t)(consumer_bytes & 0xFFU)) {
				consumer_errors++;
			}
			consumer_bytes++;
		}

		/* The producer (ISR) is uninstalled before this flag
		 * is set, so once it's set and the ring is empty,
		 * nothing more will come. */
		if (atomic_get(&isr_phase_done) != 0 &&
		    isr_ring_is_empty(&isr_ring)) {
			break;
		}
		k_usleep(50);
	}
}

static void test_isr_to_thread(void)
{
	isr_ring_init(&isr_ring, isr_ring_storage, sizeof(isr_ring_storage));
	atomic_set(&isr_phase_done, 0);
	isr_seq = 0;
	isr_bytes_accepted = 0;
	consumer_bytes = 0;
	consumer_errors = 0;

	k_thread_create(&consumer_thread, consumer_stack,
			K_THREAD_STACK_SIZEOF(consumer_stack),
			consumer_main, NULL, NULL, NULL,
			K_PRIO_COOP(5), 0, K_NO_WAIT);

	/* Real interrupt-context producer: one byte per sysclock tick. */
	sys_clock_isr_install(isr_producer);
	k_sleep(K_MSEC(300));
	sys_clock_isr_install(NULL);

	atomic_set(&isr_phase_done, 1);
	k_thread_join(&consumer_thread, K_FOREVER);

	TEST_CHECK(consumer_errors == 0);
	/* Every byte accepted by the ISR must have been consumed, in order. */
	TEST_CHECK(consumer_bytes == isr_bytes_accepted);
	TEST_CHECK(consumer_bytes > 0);
}

int main(void)
{
	test_empty();
	test_fifo_and_wrap();
	test_full();
	test_isr_to_thread();

	if (test_failures == 0) {
		printk("isr_ring self-test: PASS "
		       "(%u bytes moved ISR -> thread)\n",
		       (unsigned int)consumer_bytes);
		return 0;
	}

	printk("isr_ring self-test: FAIL (%d failures)\n", test_failures);
	return 1;
}

#endif /* ISR_RING_NO_SELF_TEST */
