static void test_full(void)
{
	static uint8_t storage[16];
	uint8_t wr[32];
	uint8_t rd[32];
	struct isr_ring rb;
	size_t i;

	isr_ring_init(&rb, storage, sizeof(storage));

	for (i = 0; i < sizeof(wr); i++) {
		wr[i] = (uint8_t)(100 + i);
	}

	/* 32 bytes into a 16-byte ring: first 16 stored, 16 dropped. */
	TEST_CHECK(isr_ring_write(&rb, wr, sizeof(wr)) == sizeof(storage));
	TEST_CHECK(isr_ring_is_full(&rb));
	TEST_CHECK(isr_ring_space_avail(&rb) == 0);
	TEST_CHECK(isr_ring_write_byte(&rb, 0xEE) == 0);	/* full: dropped */

	/* The bytes dropped must be the tail of the chunk (FIFO preserved). */
	TEST_CHECK(isr_ring_read(&rb, rd, sizeof(rd)) == sizeof(storage));
	for (i = 0; i < sizeof(storage); i++) {
		TEST_CHECK(rd[i] == wr[i]);
	}
	TEST_CHECK(isr_ring_is_empty(&rb));

	/* After draining, a full-size chunk fits again. */
	TEST_CHECK(isr_ring_write(&rb, wr, sizeof(storage)) == sizeof(storage));
	TEST_CHECK(isr_ring_read(&rb, rd, sizeof(storage)) == sizeof(storage));
	TEST_CHECK(memcmp(rd, wr, sizeof(storage)) == 0);
}
